import{_ as l,a8 as e,o as s,c as n,ah as i,K as t}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const u=JSON.parse('{"title":"RAG/客服知识库建设铁律","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["lesson","RAG","知识库","电商客服","AI"]},"headers":[],"relativePath":"vault/Memory/Lessons/RAG知识库建设铁律.md","filePath":"vault/Memory/Lessons/RAG知识库建设铁律.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Lessons/RAG知识库建设铁律.md"};function c(h,a,_,p,m,b){const o=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return s(),n("div",null,[a[0]||(a[0]=i('<h1 id="rag-客服知识库建设铁律" tabindex="-1">RAG/客服知识库建设铁律 <a class="header-anchor" href="#rag-客服知识库建设铁律" aria-label="Permalink to “RAG/客服知识库建设铁律”">​</a></h1><p>来源：帮老适客服知识库建设期（2026-07~08）的实测教训，适用于任何&quot;杂乱语料→可检索知识库&quot;场景。</p><h2 id="语料禁路径交叉引用" tabindex="-1">语料禁路径交叉引用 <a class="header-anchor" href="#语料禁路径交叉引用" aria-label="Permalink to “语料禁路径交叉引用”">​</a></h2><p>LLM 只拿到检索片段，<code>见 xxx.md</code>/<code>参照《xx》</code> 是死内容污染召回；<strong>每片段必须自包含</strong>。且只改数据文件不够——Agent 定义层（各 Agent 的指令）若仍带旧引用则下批重现。</p><h2 id="管理字段对-rag-是噪声" tabindex="-1">管理字段对 RAG 是噪声 <a class="header-anchor" href="#管理字段对-rag-是噪声" aria-label="Permalink to “管理字段对 RAG 是噪声”">​</a></h2><p>知识ID/所属库/优先级/适用对象/分类编码等列被逐步砍掉，最终只留 <code>问题|适用产品|专业术语|回答|备注</code>。产品参数类独有信息用「产品卡 schema」而非伪 Q&amp;A（17 条商品拆 4 卡+13 条安装 Q&amp;A 并入 FAQ）。入库管线注意：说明行/说明 sheet 会被当数据（干脆删除根除）。</p><h2 id="敏感场景必须配直配条目" tabindex="-1">敏感场景必须配直配条目 <a class="header-anchor" href="#敏感场景必须配直配条目" aria-label="Permalink to “敏感场景必须配直配条目”">​</a></h2><p>用户问「我爸腰突刚做完手术推荐个啥椅」，KB 无术后/腰突直配条目，LLM 兜底编出店铺不存在的品类。<strong>敏感场景（医疗/术后）不配直配条目 → LLM 兜底必出品类幻觉</strong>：基于已有商品回答、不做医疗建议。</p><h2 id="知识提炼忠实性与「人话建库」" tabindex="-1">知识提炼忠实性与「人话建库」 <a class="header-anchor" href="#知识提炼忠实性与「人话建库」" aria-label="Permalink to “知识提炼忠实性与「人话建库」”">​</a></h2><ul><li>答案不得新增客服原话未说的政策承诺（实测发现编造「可走七天无理由」）。</li><li>问题列去型号+去类目词（还原用户原话），答案去型号留类目词，商品精确绑定走元数据列——「人话建库、元数据做路由」。</li><li>同名不同物：跨表归并同名条目必须核对两边实体属性（实测「常乐椅」电商=实木餐椅 ≠ 沙发变体同名）。</li></ul><h2 id="合规红线-家具-适老品类" tabindex="-1">合规红线（家具/适老品类） <a class="header-anchor" href="#合规红线-家具-适老品类" aria-label="Permalink to “合规红线（家具/适老品类）”">​</a></h2><ul><li>家具/枕头/按摩类禁疾病宣称（失眠/颈椎病/腰疼等），只能说舒缓/辅助。</li><li>禁好评返现话术；对客禁成本/内部系统名/供应商信息。</li><li>价格优惠/议价整类不入库，一律走转人工。</li><li>红线扫描必须扫 title+content（只扫正文会漏标题里的违规），导出前先跑全量终检预扫。</li></ul><h2 id="参数口径" tabindex="-1">参数口径 <a class="header-anchor" href="#参数口径" aria-label="Permalink to “参数口径”">​</a></h2><p>参数类直接以产品表为准，产品表没有的先标「待核对」；平台导出商品属性完整度可能极低（实测 0.16），缺失字段应从详情页取而不是答「未标注」。</p>',14)),t(o),t(r)])}const f=l(d,[["render",c]]);export{u as __pageData,f as default};
